class Solution {
public:
    int smallestCommonElement(std::vector<std::vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        for (int val : mat[0]) {
            bool found = true;
            for (int r = 1; r < m; ++r) {
                if (!std::binary_search(mat[r].begin(), mat[r].end(), val)) {
                    found = false;
                    break;
                }
            }
            if (found) return val;
        }
        return -1;
    }
};

class Solution {
    public int smallestCommonElement(int[][] mat) {
        int m = mat.length;
        for (int val : mat[0]) {
            boolean found = true;
            for (int r = 1; r < m; r++) {
                if (java.util.Arrays.binarySearch(mat[r], val) < 0) {
                    found = false;
                    break;
                }
            }
            if (found) return val;
        }
        return -1;
    }
}

var smallestCommonElement = function(mat) {
    const m = mat.length, n = mat[0].length;
    const bsearch = (row, target) => {
        let l = 0, r = row.length - 1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            if (row[mid] === target) return true;
            if (row[mid] < target) l = mid + 1;
            else r = mid - 1;
        }
        return false;
    };

    for (const val of mat[0]) {
        let found = true;
        for (let r = 1; r < m; r++) {
            if (!bsearch(mat[r], val)) {
                found = false;
                break;
            }
        }
        if (found) return val;
    }
    return -1;
};
